-- Migrazione per la Fase 2: Calcolo asincrono Nura Score tramite pg_cron  -- Assumiamo che supabase abbia l'estensione pg_cron disponibile. -- NOTA: In supabase cloud, pg_cron puÃ² essere attivato via dashboard o sql CREATE EXTENSION IF NOT EXISTS pg_cron;  -- Creazione colonna per lo score pre-calcolato se non esiste -- ALTER TABLE public.tracks ADD COLUMN IF NOT EXISTS nura_score_computed FLOAT DEFAULT 0.0;  -- Creazione funzione SQL per il ricalcolo del Nura Score CREATE OR REPLACE FUNCTION public.recalculate_nura_score() RETURNS void AS $$ BEGIN     -- Esempio di CTE (Common Table Expression) descritto nel documento     -- Questo Ã¨ uno scheletro che andrÃ  adattato allo schema esatto          -- UPDATE public.tracks t     -- SET nura_score_computed = (     --     SELECT COALESCE(SUM(cf.score_modifier), 0)     --     FROM public.curator_feedback cf     --     WHERE cf.track_id = t.id     -- ) + (     --     -- Logica aggiuntiva per i likes degli utenti     --     0.0     -- );          -- Per ora facciamo un log fittizio o un'operazione sicura     RAISE NOTICE 'Nura Score recalculated'; END; $$ LANGUAGE plpgsql;  -- Schedulazione del job (ogni 15 minuti come da documento) -- Questo potrebbe richiedere privilegi di superuser, quindi meglio verificare -- su Supabase prima di eseguirlo ciecamente. -- SELECT cron.schedule('recalculate_nura_score_job', '*/15 * * * *', 'SELECT public.recalculate_nura_score()');